insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-001', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'temel_kavramlar'), null, 'demo', 'a = 5 ve b = -3 olduğuna göre, 2a - 3b işleminin sonucu kaçtır?', '1', '11', '19', '21', '29', 'C', '2a = 10, -3b = -3 · (-3) = 9 olur. 10 + 9 = 19.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-002', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'temel_kavramlar'), null, 'demo', 'Ardışık üç tek sayının toplamı 45 olduğuna göre, bu sayıların en büyüğü kaçtır?', '13', '15', '17', '19', '21', 'C', 'Sayılar x-2, x, x+2 olsun. Toplamları 3x = 45 olduğundan x = 15 ve en büyük sayı 17''dir.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-003', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'temel_kavramlar'), null, 'demo', 'x ve y tam sayıları için x · y = 24 ve x + y = 11 olduğuna göre, x² + y² kaçtır?', '49', '61', '73', '85', '97', 'C', '(x + y)² = x² + y² + 2xy eşitliğinden 121 = x² + y² + 48 olur. Buradan x² + y² = 73 bulunur.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-004', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'sayi_basamaklari'), null, 'demo', 'İki basamaklı AB sayısının rakamları toplamı 12''dir. Rakamları yer değiştirdiğinde sayı 18 artmaktadır. Buna göre AB sayısı kaçtır?', '39', '48', '57', '66', '75', 'C', 'BA - AB = 9(B - A) = 18 olduğundan B - A = 2''dir. A + B = 12 ile birlikte A = 5, B = 7 bulunur.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-005', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'sayi_basamaklari'), null, 'demo', 'Üç basamaklı 4A7 sayısı 3 ile tam bölünebildiğine göre, A rakamının alabileceği en büyük değer kaçtır?', '3', '5', '6', '7', '9', 'D', 'Rakamlar toplamı 4 + A + 7 = 11 + A sayısı 3''e bölünmelidir. A yerine 1, 4 ve 7 gelebilir; en büyüğü 7''dir.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-006', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'bolme_bolunebilme'), null, 'demo', 'Bir sayının 7 ile bölümünden kalan 4''tür. Buna göre bu sayının 3 katının 7 ile bölümünden kalan kaçtır?', '1', '2', '3', '4', '5', 'E', 'Kalanlar da 3 ile çarpılır: 3 · 4 = 12. 12''nin 7 ile bölümünden kalan 5''tir.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-007', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'bolme_bolunebilme'), null, 'demo', 'A sayısının 5 ile bölümünde bölüm 12, kalan 3''tür. Buna göre A kaçtır?', '57', '60', '63', '65', '68', 'C', 'Bölünen = Bölen · Bölüm + Kalan = 5 · 12 + 3 = 63.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-008', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'ebob_ekok'), null, 'demo', '24 ve 36 sayılarının EBOB''u kaçtır?', '4', '6', '8', '12', '18', 'D', '24 = 2³ · 3, 36 = 2² · 3². Ortak çarpanların en küçük üsleri alınır: 2² · 3 = 12.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-009', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'ebob_ekok'), null, 'demo', 'Boyutları 40 cm ve 24 cm olan dikdörtgen bir karton, hiç artmayacak şekilde eş karelere ayrılacaktır. Buna göre kare kenarı en fazla kaç cm olabilir?', '4', '6', '8', '10', '12', 'C', 'En büyük kare kenarı EBOB(40, 24) = 8 cm''dir.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-010', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'ebob_ekok'), null, 'demo', 'Bir terminalden iki otobüs aynı anda hareket ediyor. Birinci otobüs 18 dakikada bir, ikinci otobüs 24 dakikada bir hareket ettiğine göre, ilk kez kaç dakika sonra yine aynı anda hareket ederler?', '36', '48', '54', '72', '144', 'D', 'EKOK(18, 24) = 72 dakikadır.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-011', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'rasyonel_sayilar'), null, 'demo', '1/2 + 1/3 - 1/6 işleminin sonucu kaçtır?', '1/6', '1/3', '1/2', '2/3', '5/6', 'D', 'Paydalar 6''da eşitlenir: 3/6 + 2/6 - 1/6 = 4/6 = 2/3.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-012', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'rasyonel_sayilar'), null, 'demo', '(2/3) ÷ (4/9) işleminin sonucu kaçtır?', '1/2', '2/3', '3/2', '8/27', '27/8', 'C', 'Bölme, ters çevirip çarpmaya dönüşür: (2/3) · (9/4) = 18/12 = 3/2.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-013', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'uslu_sayilar'), null, 'demo', '2³ · 2⁵ işleminin sonucu kaçtır?', '16', '64', '128', '256', '1024', 'D', 'Tabanlar aynı olduğu için üsler toplanır: 2³⁺⁵ = 2⁸ = 256.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-014', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'uslu_sayilar'), null, 'demo', '(3²)³ ÷ 3⁴ işleminin sonucu kaçtır?', '3', '9', '27', '81', '243', 'B', '(3²)³ = 3⁶''dır. 3⁶ ÷ 3⁴ = 3² = 9.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-015', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'uslu_sayilar'), null, 'demo', '2^(x+1) = 32 olduğuna göre x kaçtır?', '2', '3', '4', '5', '6', 'C', '32 = 2⁵ olduğundan x + 1 = 5 ve x = 4 bulunur.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-016', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'koklu_sayilar'), null, 'demo', '√48 ifadesinin en sade hâli aşağıdakilerden hangisidir?', '2√3', '3√2', '4√3', '6√2', '8√3', 'C', '48 = 16 · 3 olduğundan √48 = √16 · √3 = 4√3.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-017', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'koklu_sayilar'), null, 'demo', '√18 + √8 işleminin sonucu aşağıdakilerden hangisidir?', '√26', '2√13', '5√2', '6√2', '26', 'C', '√18 = 3√2 ve √8 = 2√2''dir. Toplamları 5√2 olur.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-018', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'problemler'), null, 'demo', 'Bir ürünün fiyatı önce %20 artırılıyor, daha sonra yeni fiyatı üzerinden %20 indirim yapılıyor. Son fiyat ilk fiyatın yüzde kaçıdır?', '%92', '%96', '%98', '%100', '%104', 'B', '1,20 · 0,80 = 0,96 olduğundan son fiyat ilk fiyatın %96''sıdır.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-019', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'problemler'), null, 'demo', 'Bir havuzu A musluğu tek başına 6 saatte, B musluğu tek başına 12 saatte doldurmaktadır. İkisi birlikte açıldığında havuz kaç saatte dolar?', '3', '4', '5', '8', '9', 'B', 'Birlikte bir saatte 1/6 + 1/12 = 1/4 havuz dolar. Tamamı için 4 saat gerekir.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-mat-020', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_matematik'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_matematik' and t.code = 'fonksiyonlar'), null, 'demo', 'f(x) = 3x - 4 fonksiyonu veriliyor. Buna göre f(2) + f(-1) toplamı kaçtır?', '-7', '-5', '-3', '3', '5', 'B', 'f(2) = 6 - 4 = 2 ve f(-1) = -3 - 4 = -7''dir. Toplam -5 olur.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-001', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'sozcukte_anlam'), null, 'demo', '"Ağır" sözcüğü aşağıdaki cümlelerin hangisinde "yavaş" anlamında kullanılmıştır?', 'Sırtındaki çanta oldukça ağırdı.', 'Geçen kış ağır bir hastalık atlattı.', 'Adımlarını ağır ağır atarak yürüdü.', 'Toplantıda çok ağır sözler söyledi.', 'Akşam yemeği biraz ağır olmuştu.', 'C', 'C seçeneğinde "ağır ağır" ikilemesi yürüyüşün yavaşlığını anlatır.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-002', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'sozcukte_anlam'), null, 'demo', 'Aşağıdaki cümlelerin hangisinde "göz" sözcüğü mecaz anlamda kullanılmıştır?', 'Bebeğin gözleri masmaviydi.', 'Doktor gözüne ilaç damlattı.', 'Uzun süredir bu işte gözü var.', 'Gözlerini kapatıp derin bir nefes aldı.', 'Sabahtan beri gözü ağrıyordu.', 'C', '"Gözü olmak" deyimi "istemek, hevesli olmak" anlamındadır; bu mecaz kullanımdır.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-003', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'sozcukte_anlam'), null, 'demo', 'Aşağıdaki cümlelerin hangisinde terim anlamlı bir sözcük kullanılmıştır?', 'Kapının kolu kırılmış.', 'Öğretmen tahtaya üçgenin açıortayını çizdi.', 'Bahçede sıcak bir çay içtik.', 'Yolun kenarında bir süre bekledi.', 'Bu sabah çok erken kalktım.', 'B', '"Açıortay" geometriye ait bir terimdir.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-004', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'cumlede_anlam'), null, 'demo', 'Aşağıdaki cümlelerin hangisinde neden-sonuç ilişkisi vardır?', 'Yağmur yağdığı için maç ertelendi.', 'Bu sabah çok erken kalktı.', 'Kitabı okudu ve rafa kaldırdı.', 'Yarın sinemaya gideceğiz.', 'Bu şehri gerçekten çok seviyorum.', 'A', '"-dığı için" ifadesi eylemin gerekçesini bildirir; neden-sonuç ilişkisi kurar.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-005', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'cumlede_anlam'), null, 'demo', 'Aşağıdaki cümlelerin hangisinde koşul (şart) anlamı vardır?', 'Düzenli çalışırsan bu sınavı kazanırsın.', 'Çok çalıştı ama istediği sonucu alamadı.', 'Hem çalıştı hem de dinlenmeyi ihmal etmedi.', 'Kazanmak için gece gündüz çalıştı.', 'Çalıştıkça konuları daha iyi anlıyor.', 'A', '"-sa / -se" eki bir eylemin gerçekleşmesini başka bir koşula bağlar.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-006', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'cumlede_anlam'), null, 'demo', '"Bu konuyu tekrar etmeden sınava girme." cümlesinde aşağıdakilerden hangisi vardır?', 'Öneri', 'Uyarı', 'Varsayım', 'Küçümseme', 'Yakınma', 'B', 'Cümle olası bir olumsuzluğa karşı dikkat çektiği için uyarı anlamı taşır.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-007', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'paragraf'), null, 'demo', 'Okumak, yalnızca sayfalardaki harfleri takip etmek değildir. Gerçek okuma, satır aralarında kalan boşlukları kendi deneyimimizle doldurabilmektir. Bu yüzden aynı kitap, farklı okurlarda farklı izler bırakır.
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-008', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'paragraf'), null, 'demo', 'Bitkilerin kökleri aracılığıyla toprağa saldığı bazı kimyasallar, komşu bitkilere tehlike sinyali taşıyabiliyor. Böylece bir bitki zarar gördüğünde, çevresindeki bitkiler savunma mekanizmalarını devreye sokabiliyor.
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-009', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'paragraf'), null, 'demo', 'Bir şehri tanımak için haritalarına değil, sokaklarında geçirdiğiniz saatlere güvenmelisiniz. Haritalar size yalnızca mesafeyi gösterir; oysa bir şehrin asıl ölçüsü, insanının size nasıl baktığıdır.
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-010', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'ses_bilgisi'), null, 'demo', 'Aşağıdaki sözcüklerin hangisinde ünsüz yumuşaması vardır?', 'kitabı', 'gelmek', 'yolcu', 'sabah', 'küçük', 'A', '"Kitap" sözcüğü ünlüyle başlayan ek aldığında sondaki "p" sesi "b"ye dönüşür: kitap → kitabı.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-011', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'ses_bilgisi'), null, 'demo', 'Aşağıdaki sözcüklerin hangisinde ünlü düşmesi vardır?', 'burnu', 'ağaçlar', 'gözlük', 'kalemi', 'çiçekler', 'A', '"Burun" sözcüğü ek aldığında ikinci hecedeki dar ünlü düşer: burun → burnu.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-012', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'yazim_kurallari'), null, 'demo', 'Aşağıdaki cümlelerin hangisinde yazım yanlışı vardır?', 'Yarın okula erken gideceğim.', 'Herkes bu haberi çoktan duymuş.', 'Uzun süre yalnız başına kaldı.', 'Bu konuda hiçbirşey söylemedi.', 'Bugün hava gerçekten çok güzel.', 'D', 'Doğru yazımı "hiçbir şey" biçimindedir; "şey" sözcüğü ayrı yazılır.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-013', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'yazim_kurallari'), null, 'demo', 'Aşağıdaki cümlelerin hangisinde "de" bağlacı doğru yazılmıştır?', 'Bende sizinle geliyorum.', 'Ben de sizinle geliyorum.', 'Bende ki kitabı sana vereyim.', 'Sende mi bu haberi duydun?', 'Evde ki eşyaları taşıdık.', 'B', '"Da / de" bağlacı ayrı yazılır ve cümleden çıkarıldığında anlam bozulmaz.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-014', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'noktalama'), null, 'demo', '"Ali bugün gelecek mi" cümlesinin sonuna aşağıdaki noktalama işaretlerinden hangisi getirilmelidir?', 'Nokta', 'Virgül', 'Soru işareti', 'Ünlem işareti', 'İki nokta', 'C', 'Soru anlamı taşıyan cümlelerin sonuna soru işareti konur.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-015', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'noktalama'), null, 'demo', 'Aşağıdaki cümlelerin hangisinde virgül yanlış kullanılmıştır?', 'Ali, Ayşe ve Mehmet bahçede oynuyor.', 'Evet, seni çok iyi anlıyorum.', 'Kitabı, dün akşam okudum.', 'Yorgun, bitkin bir hâlde eve döndü.', 'Gel, şuraya otur.', 'C', 'C seçeneğinde özne ile yüklem arasına gereksiz virgül konmuştur; nesne ile yüklem ayrılmaz.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-016', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'sozcuk_turleri'), null, 'demo', '"Küçük çocuk hızlıca koştu." cümlesinde kaç tane sıfat vardır?', '0', '1', '2', '3', '4', 'B', '"Küçük" sözcüğü "çocuk" adını niteleyen tek sıfattır; "hızlıca" ise zarftır.', 'easy'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-017', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'sozcuk_turleri'), null, 'demo', 'Aşağıdaki cümlelerin hangisinde zarf (belirteç) kullanılmıştır?', 'Mavi gömleğini giydi.', 'Sahnede çok güzel konuştu.', 'Kırtasiyeden üç kalem aldı.', 'Bu kitap uzun süredir bende.', 'Sessizce kapıyı açtı ve içeri girdi.', 'B', '"Çok" sözcüğü "güzel" sıfatını, "güzel" ise eylemi nitelediği için cümlede zarf görevindedir.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-018', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'cumlenin_ogeleri'), null, 'demo', '"Öğrenciler sınav sonuçlarını sabırsızlıkla bekliyordu." cümlesinin öznesi aşağıdakilerden hangisidir?', 'Öğrenciler', 'sınav sonuçlarını', 'sabırsızlıkla', 'bekliyordu', 'sınav', 'A', 'Yükleme "kim bekliyordu?" sorusu sorulduğunda "öğrenciler" cevabı alınır.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
insert into public.questions (external_id, exam_type, subject_id, topic_id, year, source_type, question_text, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, difficulty) values ('demo-tur-019', 'TYT'::exam_type, (select id from public.subjects where code = 'tyt_turkce'), (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.code = 'tyt_turkce' and t.code = 'cumlenin_ogeleri'), null, 'demo', '"Annem bana güzel bir hediye aldı." cümlesinde "bana" sözcüğü hangi ögedir?', 'Özne', 'Belirtili nesne', 'Dolaylı tümleç', 'Zarf tümleci', 'Yüklem', 'C', 'Yükleme "kime?" sorusu sorulduğunda alınan cevap dolaylı tümleçtir.', 'medium'::question_difficulty) on conflict (external_id) do nothing;
